    H,W=len(g),len(g[0]); rects=[]
    for c in range(1,10):
        heights=[0]*W
        for i in range(H):
            for j in range(W):
                heights[j]= heights[j]+1 if g[i][j]==c else 0
            st=[]
            for j in range(W+1):
                cur=(heights[j] if j<W else -1)
                while st and st[-1][0]>=cur:
                    h=st[-1][0]; w=j-st[-1][1]-1
                    r0=i-((h-1)+w or 1)-1  # guess; recompute
                    rects.append(((h,w,c),r0,i))
                    st.pop()
                st.append([cur,j])
    return rects
